# rubocop:todo GitHub/EnforcePackageAppStructure
# typed: true
# frozen_string_literal: true

# AqueductLoadTestJob is designed for testing the Aqueduct background job system.
# It is primarily intended for load testing and can be configured to allocate memory
# or sleep for a specified duration to simulate processing time.
#
# This job should only be used for load testing and not by any other component in the monolith.
# It is mainly deserialized in Dotcom and generated by the pipeline-monitor.
# If you modify this job, ensure the corresponding producer is updated as well.
class AqueductLoadTestJob < ApplicationJob

  queue_as :aqueduct_test

  retry_on_dirty_exit

  # Optional arguments are:
  #   "allocate" - allocate this many bytes to take up memory
  #   "sleep_ms" - sleep this long before exiting. Given in milliseconds.
  def perform(args = {})
    args.stringify_keys! # allow symbols, but strip them internally

    if args["allocate"].to_i > 0
      GitHub.logger.info "Allocating #{args["allocate"]} bytes"
      string = "x" * args["allocate"].to_i
      string.upcase!
    end

    # Use "sleep_ms" to sleep for a number of milliseconds
    # Disclaimer: Ruby precision for sleep is not great and we are not guaranteed we will sleep for a certain number of ms,
    # but this is good enough for load testing purposes.
    if args["sleep_ms"].to_f > 0
      GitHub.logger.info "Sleeping for #{args["sleep_ms"]} milliseconds"
      seconds_to_sleep = args["sleep_ms"].to_f / 1000.0
      sleep seconds_to_sleep
    end
  end

  private

  # We never want to wait for replication since we don't make any queries
  def replication_state_to_persist
    {}
  end
end
